import{S as r,o as n,c,a9 as a,B as d}from"./chunks/framework.DxG24V0C.js";const s="/agentsrc/images/opencode/index-architecture.svg",i="/agentsrc/images/opencode/01-layers.svg",l="/agentsrc/images/opencode/01-chain.svg",p="/agentsrc/images/opencode/01-extensions.svg",q=JSON.parse('{"title":"OpenCode 整体架构：一个 10 万行 Agent 如何组织为一条装配链","description":"","frontmatter":{"title":"OpenCode 整体架构：一个 10 万行 Agent 如何组织为一条装配链"},"headers":[],"relativePath":"opencode/01-overview.md","filePath":"opencode/01-overview.md","lastUpdated":1788319991000}'),g={name:"opencode/01-overview.md"},b=Object.assign(g,{setup(h){const o=[{question:"OpenCode 把引擎拆成 core / llm / opencode 三包，依赖方向最准确的是？",options:["'opencode' 依赖 'core' 与 'llm'，'core' 做底座不依赖任何内部包，'llm' 独立协议层","'core' 依赖 'opencode' 和 'llm'，因为实现要在契约之上","三个包互相循环依赖，谁都依赖谁，靠 Effect 解耦","'llm' 是最底层，反过来依赖 'opencode' 的运行时才能找回厂商"],correct:0,explanation:"core 是最底底座（无内部依赖），llm 独立中立，opencode 依赖 core+llm+sdk+plugin+ui 做装配。三个包依赖方向清晰单向，才能化整为零。"},{question:"厂商接入的核心设计是什么？",options:["在代码里写死 N 家厂商标记，硬编码判断走哪个","core/plugin/provider 里放 N 个适配器，向 core 插一个即可接入新厂商","model 不作为变量，每个厂商一个独立分支的 prompt 模板","用一个巨型条件分支在运行时逐个判断走哪家模型"],correct:1,explanation:"厂商接入是「往 core 的 provider/ 目录插 adapter」的可插拔方式，所以能接 30+ 家而不乱。选项 A/D 是静态写死，C 与事实不符。"},{question:"关于「单一入口」，正确的是？",options:["CLI 和 Web 用两套独立引擎分别实现，入口不同需要并行维护两份","有一个 index.ts 单一入口，跑 serve 同进程开 HTTP + WebSocket","入口只有一个 serve 命令，不支持 CLI，必须走 HTTP","每个子命令都编译成一个独立二进制，无共享装配"],correct:1,explanation:"cli 和 web 等等是同一套引擎同一入口，靠 index.ts(serve 等子命令)装配，同进程开出 HTTP API 和 WebSocket。"},{question:"将持久化方案从 JSONL 替换为 SQLite + Drizzle，主要是出于怎样的架构考量？",options:["它是 append-only 的纯文本，适合日志级的顺序追加与手工翻阅","它把会话状态落到可结构化查询的底座，能审计能恢复","它牺牲查询能力换取最小的安装体积，只承担轻量存取不是会话续命","它只适合单机一次性写入，无法支撑多次会话之间的状态重建"],correct:1,explanation:"SQLite + Drizzle 支撑结构化查询与事务，让会话状态能审计、能恢复，而不是只靠 append-only JSONL 的手工可读。"},{question:"「装配链」为什么是开这篇的核心？",options:["证明主循环写得足够漂亮，靠一条循环就能压住 Agent 的随意输出","把复杂度切成「入口→运行时→主循环→工具→持久化/扩展」各段，层层可替换，才得以大而不乱","证明这个项目的代码行数全网最少，所以读起来天然轻松","证明单个模型足够强大，一套提示词就能统摄所有子系统的细节"],correct:1,explanation:"核心哲学：靠一条可断可换、各守一段的装配链把快 10 万行化整为零，架构追求「大纲美」而非一行代码。"}];return(u,e)=>{const t=r("Quiz");return n(),c("div",null,[e[0]||(e[0]=a("",65)),d(t,{questions:o})])}}});export{q as __pageData,b as default};
